import java.util.*; import java.io.*; public class Main { static class FastScanner { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st; String next() { while (st == null || !st.hasMoreTokens()) { try { String l = br.readLine(); if (l == null) return null; st = new StringTokenizer(l); } catch (IOException e) { return null; } } return st.nextToken(); } int nextInt() { return Integer.parseInt(next()); } } public static void main(String[] args) throws Exception { FastScanner sc = new FastScanner(); PrintWriter out = new PrintWriter(System.out); String tStr = sc.next(); if (tStr != null) { int t = Integer.parseInt(tStr); while (t-- > 0) { int n = sc.nextInt(); int[] p = new int[n]; for (int i = 0; i < n; i++) { p[i] = sc.nextInt(); } int count = 0; for (int i = 0; i < n; i++) { if (p[i] == i + 1) { if (i + 1 < n && p[i + 1] == i + 2) { count++; i++; } else { count++; } } } out.println(count); } } out.flush(); out.close(); } }